transforms.code:
try:
	if value == None:
		return ''
	else:
		return value

except:
	return ''

try:
	if value < 0:
		return '00:00:00'
	else:
		seconds = value
		minutes, seconds = divmod(seconds, 60)
		hours, minutes = divmod(minutes, 60)

		return "{:02d}:{:02d}:{:02d}".format(hours, minutes, seconds)

except:
	return '00:00:00'

